  "dont": [
   {
    "t": "متحوّلش فلوس بويسترن يونيون أو موني جرام لحد أونلاين.",
    "src": "ftc:romance-scam"
   },
   {
    "t": "متحطّش فلوس على كروت هدايا وتدّي حد كود الـPIN.",
    "src": "ftc:romance-scam"
   },
   {
    "t": "متحوّلش عملات رقمية ولا تدخل \"استثمار كريبتو\" هو عرضه عليك.",
    "src": "ftc:romance-scam"
   },
   {
    "t": "متخليش استعجاله وضغطه يخلّيك تدفع من غير ما تفكّر.",
    "src": "ftc:romance-scam"
   }
  ],
  "whenWhy": {
   "ar": "النصّابين بيبنوا الثقة على مهل — بيكلّموك كذا مرة في اليوم — وبعدين يخترعوا قصة عاجلة عشان يضغطوا عليك تدفع بطريقة صعب ترجّع بيها فلوسك (تحويل، كروت هدايا، كريبتو). ساعة ما حد قابلته أونلاين بس يطلب فلوس، ده وقت الخطر اللي المفروض تقف فيه."
  },
  "note": {
   "ar": "المصدر منظمة أمريكية (FTC)، بس نفس الحيَل وطرق الدفع (تحويل، كروت هدايا، كريبتو) بتحصل في مصر بالظبط. لو اتنصب عليك، أسرع خطوة هي تكلّم البنك وتبلّغ محليًا. قناة التبليغ الرسمية عند المصدر نفسه هي ReportFraud.ftc.gov (خاصة بأمريكا)."
  },
  "basis": {
   "ar": ""
  },
  "quote": "\"Never send money or gifts to a sweetheart you haven't met in person.\"",
  "contacts": [
   {
    "label": "بنكك أو شركة التحويل / الكارت",
    "number": "",
    "say": "لو دفعت ببطاقة أو تحويل أو كارت هدايا أو عملة رقمية، كلّم البنك أو الشركة على طول، قولّهم اتنصب عليك واطلب استرجاع فلوسك."
   },
   {
    "label": "بلّغ الجهات المختصة والمنصة",
    "number": "",
    "say": "قدّم بلاغ لمباحث الإنترنت أو النيابة في مصر بأقرب قسم، وبلّغ الموقع أو التطبيق اللي اتعرّفت عليه فيه؛ خُد معاك المحادثات وإيصالات التحويل."
   }
  ],
